/**
 * 音频channel layout定义，与内核保持一致
 *
 * @author karlyczhang
 * @date 2024/03/05
 */
export const enum TPChannelLayout {
  TP_CH_UNKNOWN = 0x00000000,
  TP_CH_FRONT_LEFT = 0x00000001,
  TP_CH_FRONT_RIGHT = 0x00000002,
  TP_CH_FRONT_CENTER = 0x00000004,
  TP_CH_LOW_FREQUENCY = 0x00000008,
  TP_CH_BACK_LEFT = 0x00000010,
  TP_CH_BACK_RIGHT = 0x00000020,
  TP_CH_FRONT_LEFT_OF_CENTER = 0x00000040,
  TP_CH_FRONT_RIGHT_OF_CENTER = 0x00000080,
  TP_CH_BACK_CENTER = 0x00000100,
  TP_CH_SIDE_LEFT = 0x00000200,
  TP_CH_SIDE_RIGHT = 0x00000400,
  TP_CH_TOP_CENTER = 0x00000800,
  TP_CH_TOP_FRONT_LEFT = 0x00001000,
  TP_CH_TOP_FRONT_CENTER = 0x00002000,
  TP_CH_TOP_FRONT_RIGHT = 0x00004000,
  TP_CH_TOP_BACK_LEFT = 0x00008000,
  TP_CH_TOP_BACK_CENTER = 0x00010000,
  TP_CH_TOP_BACK_RIGHT = 0x00020000,
  TP_CH_STEREO_LEFT = 0x20000000, ///< Stereo downmix.
  TP_CH_STEREO_RIGHT = 0x40000000, ///< See TP_CH_STEREO_LEFT.
  TP_CH_WIDE_LEFT = 0x0000000080000000,
  TP_CH_WIDE_RIGHT = 0x0000000100000000,
  TP_CH_SURROUND_DIRECT_LEFT = 0x0000000200000000,
  TP_CH_SURROUND_DIRECT_RIGHT = 0x0000000400000000,
  TP_CH_LOW_FREQUENCY_2 = 0x0000000800000000,
  TP_CH_TOP_SIDE_LEFT = (1 << 36),
  TP_CH_TOP_SIDE_RIGHT = (1 << 37),
  TP_CH_BOTTOM_FRONT_CENTER = (1 << 38),
  TP_CH_BOTTOM_FRONT_LEFT = (1 << 39),
  TP_CH_BOTTOM_FRONT_RIGHT = (1 << 40),
  TP_CH_LAYOUT_NATIVE = 0x8000000000000000,

  TP_CH_LAYOUT_MONO = (TP_CH_FRONT_CENTER),
  TP_CH_LAYOUT_STEREO = (TP_CH_FRONT_LEFT | TP_CH_FRONT_RIGHT),
  TP_CH_LAYOUT_2POINT1 = (TP_CH_LAYOUT_STEREO | TP_CH_LOW_FREQUENCY),
  TP_CH_LAYOUT_2_1 = (TP_CH_LAYOUT_STEREO | TP_CH_BACK_CENTER),
  TP_CH_LAYOUT_SURROUND = (TP_CH_LAYOUT_STEREO | TP_CH_FRONT_CENTER),
  TP_CH_LAYOUT_3POINT1 = (TP_CH_LAYOUT_SURROUND | TP_CH_LOW_FREQUENCY),
  TP_CH_LAYOUT_4POINT0 = (TP_CH_LAYOUT_SURROUND | TP_CH_BACK_CENTER),
  TP_CH_LAYOUT_4POINT1 = (TP_CH_LAYOUT_4POINT0 | TP_CH_LOW_FREQUENCY),
  TP_CH_LAYOUT_2_2 = (TP_CH_LAYOUT_STEREO | TP_CH_SIDE_LEFT | TP_CH_SIDE_RIGHT),
  TP_CH_LAYOUT_QUAD = (TP_CH_LAYOUT_STEREO | TP_CH_BACK_LEFT | TP_CH_BACK_RIGHT),
  TP_CH_LAYOUT_5POINT0 = (TP_CH_LAYOUT_SURROUND | TP_CH_SIDE_LEFT | TP_CH_SIDE_RIGHT),
  TP_CH_LAYOUT_5POINT1 = (TP_CH_LAYOUT_5POINT0 | TP_CH_LOW_FREQUENCY),
  TP_CH_LAYOUT_5POINT0_BACK = (TP_CH_LAYOUT_SURROUND | TP_CH_BACK_LEFT | TP_CH_BACK_RIGHT),
  TP_CH_LAYOUT_5POINT1_BACK = (TP_CH_LAYOUT_5POINT0_BACK | TP_CH_LOW_FREQUENCY),
  TP_CH_LAYOUT_6POINT0 = (TP_CH_LAYOUT_5POINT0 | TP_CH_BACK_CENTER),
  TP_CH_LAYOUT_6POINT0_FRONT = (TP_CH_LAYOUT_2_2 | TP_CH_FRONT_LEFT_OF_CENTER | TP_CH_FRONT_RIGHT_OF_CENTER),
  TP_CH_LAYOUT_HEXAGONAL = (TP_CH_LAYOUT_5POINT0_BACK | TP_CH_BACK_CENTER),
  TP_CH_LAYOUT_6POINT1 = (TP_CH_LAYOUT_5POINT1 | TP_CH_BACK_CENTER),
  TP_CH_LAYOUT_6POINT1_BACK = (TP_CH_LAYOUT_5POINT1_BACK | TP_CH_BACK_CENTER),
  TP_CH_LAYOUT_6POINT1_FRONT = (TP_CH_LAYOUT_6POINT0_FRONT | TP_CH_LOW_FREQUENCY),
  TP_CH_LAYOUT_7POINT0 = (TP_CH_LAYOUT_5POINT0 | TP_CH_BACK_LEFT | TP_CH_BACK_RIGHT),
  TP_CH_LAYOUT_7POINT0_FRONT = (TP_CH_LAYOUT_5POINT0 | TP_CH_FRONT_LEFT_OF_CENTER | TP_CH_FRONT_RIGHT_OF_CENTER),
  TP_CH_LAYOUT_7POINT1 = (TP_CH_LAYOUT_5POINT1 | TP_CH_BACK_LEFT | TP_CH_BACK_RIGHT),
  TP_CH_LAYOUT_7POINT1_WIDE = (TP_CH_LAYOUT_5POINT1 | TP_CH_FRONT_LEFT_OF_CENTER | TP_CH_FRONT_RIGHT_OF_CENTER),
  TP_CH_LAYOUT_7POINT1_WIDE_BACK =
  (TP_CH_LAYOUT_5POINT1_BACK | TP_CH_FRONT_LEFT_OF_CENTER | TP_CH_FRONT_RIGHT_OF_CENTER),
  TP_CH_LAYOUT_OCTAGONAL = (TP_CH_LAYOUT_5POINT0 | TP_CH_BACK_LEFT | TP_CH_BACK_CENTER | TP_CH_BACK_RIGHT),
  TP_CH_LAYOUT_HEXADECAGONAL =
  (TP_CH_LAYOUT_OCTAGONAL | TP_CH_WIDE_LEFT | TP_CH_WIDE_RIGHT | TP_CH_TOP_BACK_LEFT | TP_CH_TOP_BACK_RIGHT
    | TP_CH_TOP_BACK_CENTER | TP_CH_TOP_FRONT_CENTER | TP_CH_TOP_FRONT_LEFT | TP_CH_TOP_FRONT_RIGHT),
  TP_CH_LAYOUT_STEREO_DOWNMIX = (TP_CH_STEREO_LEFT | TP_CH_STEREO_RIGHT),
  TP_CH_LAYOUT_22POINT2 =
  (TP_CH_LAYOUT_5POINT1_BACK | TP_CH_FRONT_LEFT_OF_CENTER | TP_CH_FRONT_RIGHT_OF_CENTER
    | TP_CH_BACK_CENTER | TP_CH_LOW_FREQUENCY_2 | TP_CH_SIDE_LEFT | TP_CH_SIDE_RIGHT | TP_CH_TOP_FRONT_LEFT
    | TP_CH_TOP_FRONT_RIGHT | TP_CH_TOP_FRONT_CENTER | TP_CH_TOP_CENTER | TP_CH_TOP_BACK_LEFT
    | TP_CH_TOP_BACK_RIGHT | TP_CH_TOP_SIDE_LEFT | TP_CH_TOP_SIDE_RIGHT | TP_CH_TOP_BACK_CENTER
    | TP_CH_BOTTOM_FRONT_CENTER | TP_CH_BOTTOM_FRONT_LEFT | TP_CH_BOTTOM_FRONT_RIGHT),
  TP_CH_LAYOUT_10POINT2 =
  (TP_CH_LAYOUT_7POINT1_WIDE_BACK | TP_CH_TOP_FRONT_LEFT | TP_CH_TOP_FRONT_RIGHT
    | TP_CH_BACK_CENTER | TP_CH_LOW_FREQUENCY_2),
  TP_CH_LAYOUT_5POINT1POINT2 = (TP_CH_LAYOUT_5POINT1 | TP_CH_TOP_FRONT_LEFT | TP_CH_TOP_FRONT_RIGHT),
  TP_CH_LAYOUT_5POINT1POINT4 = (TP_CH_LAYOUT_5POINT1POINT2 | TP_CH_TOP_BACK_LEFT | TP_CH_TOP_BACK_RIGHT),
  TP_CH_LAYOUT_7POINT1POINT2 = (TP_CH_LAYOUT_7POINT1 | TP_CH_TOP_FRONT_LEFT | TP_CH_TOP_FRONT_RIGHT),
  TP_CH_LAYOUT_7POINT1POINT4 =
  (TP_CH_LAYOUT_7POINT1 | TP_CH_TOP_FRONT_LEFT | TP_CH_TOP_FRONT_RIGHT | TP_CH_TOP_BACK_LEFT
    | TP_CH_TOP_BACK_RIGHT),
}
